class Solution{public:vector<int>sumOfDistancesInTree(int n,vector<vector<int>>&e){vector<vector<int>>g(n);for(auto&x:e)g[x[0]].push_back(x[1]),g[x[1]].push_back(x[0]);vector<int>sz(n,1),d(n),r(n);function<void(int,int)>a=[&](int u,int p){for(int v:g[u])if(v!=p){a(v,u);sz[u]+=sz[v];d[u]+=d[v]+sz[v];}};function<void(int,int)>b=[&](int u,int p){for(int v:g[u])if(v!=p){r[v]=r[u]-sz[v]+n-sz[v];b(v,u);}};a(0,-1);r[0]=d[0];b(0,-1);return r;}};
